begin;

-- CLASS_INTEGRATION_STRICT: class:cleric
-- CLASS_PACKAGE_TEST: tests/clericTextReady.test.ts
-- CLASS_WORK_STATUS: cleric:text=READY;mechanics=NOT_AUDITED
-- CLASS_STATUS_LEDGER: src/rule-templates/CLASS_WORK_STATUS.md
-- Presentation-only Cleric closure. This migration changes human-facing labels,
-- descriptions, author comments and renderer-only presentation metadata only.
-- It does NOT create, delete or rewrite resources, actions, formulas, effects,
-- costs, choices, spell access or Character Engine dependencies.

create or replace function private.cleric_patch_feature_text(
  p_campaign_id uuid,
  p_catalog_key text,
  p_level integer,
  p_source_key text,
  p_label text,
  p_description text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_template uuid;
begin
  select id into v_template
  from public.rule_templates
  where campaign_id=p_campaign_id and is_active and catalog_key=p_catalog_key
  order by version desc limit 1;
  if v_template is null then return; end if;

  if p_source_key='hit-die' and p_catalog_key='class:cleric' then
    update public.rule_templates t
    set mechanics=coalesce((
      select jsonb_agg(
        case when m->>'type'='grant' and m->>'target'='feature' and m->>'sourceKey'=p_source_key
          then jsonb_set(jsonb_set(m,'{payload,label}',to_jsonb(p_label),true),'{payload,description}',to_jsonb(p_description),true)
          else m end order by ord
      )
      from jsonb_array_elements(coalesce(t.mechanics,'[]'::jsonb)) with ordinality q(m,ord)
    ),'[]'::jsonb)
    where t.id=v_template;
    return;
  end if;

  update public.rule_template_levels l
  set mechanics=coalesce((
    select jsonb_agg(
      case when m->>'type'='grant' and m->>'target'='feature' and m->>'sourceKey'=p_source_key
        then jsonb_set(jsonb_set(m,'{payload,label}',to_jsonb(p_label),true),'{payload,description}',to_jsonb(p_description),true)
        else m end order by ord
    )
    from jsonb_array_elements(coalesce(l.mechanics,'[]'::jsonb)) with ordinality q(m,ord)
  ),'[]'::jsonb)
  where l.template_id=v_template and l.level=p_level;
end;
$$;

create or replace function private.cleric_voss_feature_comment(p_label text,p_description text,p_source_key text)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_description text := lower(coalesce(p_description,''));
  v_seed integer := mod(char_length(coalesce(p_label,''))+char_length(coalesce(p_source_key,'')),6);
begin
  if v_description ~ '(леч|исцел|восстанавлив.{0,18}hp|умирающ|временн.{0,8}hp)' then
    return (array[
      'Жрецы называют это милостью. Раненые обычно не спорят с терминологией, пока кровь остаётся внутри.',
      'Хорошее лечение не делает вас бессмертным. Оно просто даёт ещё один шанс принять то же плохое решение.',
      'Лекарь всегда знает, кто в отряде считает собственную кровь общим расходником. Обычно это самый громкий человек.',
      'Вернуть бойца на ноги полезно. Объяснить ему, почему не стоит снова лезть под тот же топор, заметно сложнее.',
      'Могильщики ненавидят хорошие лечебные чудеса. Редкий профессиональный конфликт, которому я искренне рад.',
      'Пока остальные называют это героизмом, жрец занимается бухгалтерией ран. Кто-то же должен считать убытки.'
    ])[v_seed+1];
  elsif v_description ~ '(сопротивлен|кд|укрыти|помех|защит|спасброс|брон)' then
    return (array[
      'Защита особенно хороша за миг до того, как становится поздно. После — это уже работа могильщика.',
      'Пережить удар — ещё не победа. Но мёртвые спорят с этим заметно реже.',
      'Надёжная защита выглядит скучно ровно до того момента, когда рядом падает человек без неё.',
      'Чудо, которое не даёт умереть, ценнее чуда с красивым названием. Реклама храмов утверждает обратное.',
      'Если враг вынужден ударить дважды, это уже почти экономическая победа.',
      'Броня, вера и здравый смысл решают одну задачу. Последний ресурс у приключенцев встречается реже всего.'
    ])[v_seed+1];
  elsif v_description ~ '(атак|урон|некрот|сияющ|огн|гром|электр|оруж|крит|удар)' then
    return (array[
      'Удивительно, как быстро богословский спор становится понятнее после правильно приложенного оружия.',
      'Святое насилие отличается от обычного главным образом тем, что после него кто-то пишет гимн.',
      'Если чудо заканчивает спор быстрее меча, я не возражаю. Меч, впрочем, тоже держал бы рядом.',
      'Боги любят символы. Противник обычно лучше понимает дыру в доспехе.',
      'Хороший удар не требует проповеди. Это, пожалуй, его главное преимущество перед жрецом.',
      'Когда небеса начинают считать урон, смертным разумнее перестать спорить о вероучении.'
    ])[v_seed+1];
  elsif v_description ~ '(телепорт|перемест|скорост|полет|полёт|дальность|фут)' then
    return (array[
      'Ноги спасли больше святых, чем жития готовы признать. Иногда бог просто помогает ими пользоваться быстрее.',
      'Правильное место в бою — там, где враг не успел подготовить для вас могилу.',
      'Расстояние — отличная защита. Особенно если преодолеваете его вы, а не вооружённая толпа.',
      'Чудесное перемещение всё ещё считается бегством, если после него вы не вернулись. Я не осуждаю.',
      'Стоять на месте ради достоинства удобно только памятникам.',
      'Если молитва позволяет оказаться подальше от клинка, это одна из немногих молитв с очевидным ответом.'
    ])[v_seed+1];
  elsif v_description ~ '(заклин|магичес|прориц|некромант|заговор|ячейк)' then
    return (array[
      'Магия от бога всё ещё магия. Просто жалобу на последствия приходится отправлять заметно выше.',
      'Жрец скажет, что чудо даровано. Я скажу, что расход всё равно лучше считать заранее.',
      'Когда молитва начинает делать работу инструмента, я перестаю спорить с молитвой.',
      'Небеса дают силу без инструкции по технике безопасности. Видимо, естественный отбор тоже часть учения.',
      'Чудеса хороши тем, что работают. Богословие можно обсудить после того, как перестанут лететь стрелы.',
      'Если результат можно проверить на месте, меня устраивает даже божественный поставщик.'
    ])[v_seed+1];
  elsif v_description ~ '(очарован|команд|телепати|язык|навык|экспертиз|провер)' then
    return (array[
      'Слова дешевле стрел, пока не выясняется, сколько людей готовы убить за неправильно выбранное.',
      'Убедить человека полезнее, чем лечить его после драки. Жрецы иногда доходят до этой мысли самостоятельно.',
      'Знание редко выглядит героически. Зато после него обычно требуется меньше носилок.',
      'Если можно решить проблему разговором, решайте. Стрелы потом пригодятся для людей, которые разговаривать отказались.',
      'Чужая голова — опасное место для прогулок. Особенно если хозяин внезапно заметил посетителя.',
      'Команда работает лучше, когда за ней стоит что-то кроме громкого голоса. Например, разгневанное божество.'
    ])[v_seed+1];
  else
    return (array[
      'Редкое чудо: правило полезнее его торжественного названия. Пользуйтесь, пока небеса не прислали счёт.',
      'Жрец назовёт это даром. Я предпочитаю слово «инструмент» — оно реже портит людям характер.',
      'Полезная способность. Это высшая похвала, которую религиозная практика от меня сегодня получит.',
      'Запомните условие применения. Кладбища полны людей, которые помнили только красивую часть.',
      'Если это помогает вернуться из похода живым, происхождение можно обсудить уже в таверне.',
      'Божественная помощь хороша до тех пор, пока человек не начинает принимать её за замену здравому смыслу.'
    ])[v_seed+1];
  end if;
end;
$$;

create or replace function private.cleric_voss_mechanics(p_mechanics jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_agg(
    case when m->>'type'='grant' and m->>'target'='feature' then
      jsonb_set(m,'{payload,authorComment}',to_jsonb(private.cleric_voss_feature_comment(m->'payload'->>'label',m->'payload'->>'description',m->>'sourceKey')),true)
    else m end order by ord
  ),'[]'::jsonb)
  from jsonb_array_elements(case when jsonb_typeof(coalesce(p_mechanics,'[]'::jsonb))='array' then coalesce(p_mechanics,'[]'::jsonb) else '[]'::jsonb end) with ordinality q(m,ord);
$$;

create or replace function private.cleric_voss_choice(p_choice jsonb)
returns jsonb
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_result jsonb:=coalesce(p_choice,'{}'::jsonb);
  v_options jsonb;
  v_levels jsonb;
begin
  if jsonb_typeof(v_result->'option_mechanics')='object' then
    select coalesce(jsonb_object_agg(k,private.cleric_voss_mechanics(v)),'{}'::jsonb) into v_options
    from jsonb_each(v_result->'option_mechanics') q(k,v);
    v_result:=jsonb_set(v_result,'{option_mechanics}',v_options,true);
  end if;
  if jsonb_typeof(v_result->'option_mechanics_by_level')='object' then
    select coalesce(jsonb_object_agg(option_key,patched_levels),'{}'::jsonb) into v_levels
    from (
      select option_key,
        (select coalesce(jsonb_object_agg(level_key,private.cleric_voss_mechanics(level_value)),'{}'::jsonb)
         from jsonb_each(option_levels) l(level_key,level_value)) as patched_levels
      from jsonb_each(v_result->'option_mechanics_by_level') o(option_key,option_levels)
    ) s;
    v_result:=jsonb_set(v_result,'{option_mechanics_by_level}',v_levels,true);
  end if;
  return v_result;
end;
$$;

create or replace function private.cleric_voss_choices(p_choices jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_agg(private.cleric_voss_choice(v) order by ord),'[]'::jsonb)
  from jsonb_array_elements(case when jsonb_typeof(coalesce(p_choices,'[]'::jsonb))='array' then coalesce(p_choices,'[]'::jsonb) else '[]'::jsonb end) with ordinality q(v,ord);
$$;

create or replace function private.cleric_domain_voss(p_catalog_key text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_catalog_key
    when 'subclass:cleric:arcana-domain' then 'Жрец, который полез в волшебные учебники. Будто одного источника неприятностей ему было мало.'
    when 'subclass:cleric:death-domain' then 'Служители смерти любят говорить о неизбежности. Особенно убедительно это звучит со стороны живого человека.'
    when 'subclass:cleric:forge-domain' then 'Бог кузни хотя бы честен: сначала молот, потом результат. Без трёх часов проповеди о символизме молота.'
    when 'subclass:cleric:grave-domain' then 'Хороший хранитель могилы знает, кого туда пускать, а кого ещё рано. Полезная избирательность.'
    when 'subclass:cleric:knowledge-domain' then 'Они знают слишком много и всё равно идут в подземелье. Значит, знание само по себе от глупости не лечит.'
    when 'subclass:cleric:life-domain' then 'Если такой жрец велит отойти назад, отойдите. Обычно он уже посчитал вашу кровь точнее вас.'
    when 'subclass:cleric:light-domain' then 'Свет истины прекрасен. Особенно когда он достаточно яркий, чтобы враг перестал видеть вас в ответ.'
    when 'subclass:cleric:nature-domain' then 'Друид в храмовой одежде. Деревья те же, только теперь у них появилась канцелярия.'
    when 'subclass:cleric:order-domain' then 'Когда закон получает магию, спор с чиновником наконец становится буквально опасным для здоровья.'
    when 'subclass:cleric:peace-domain' then 'Миротворец, который умеет встать под чужой удар, заслуживает уважения. Или обследования. Иногда обоих.'
    when 'subclass:cleric:tempest-domain' then 'Если молитва отвечает громом, я бы не стал просить повторить ответ погромче.'
    when 'subclass:cleric:trickery-domain' then 'Жрец обмана доказывает, что даже богам иногда нужен человек, способный соврать профессионально.'
    when 'subclass:cleric:twilight-domain' then 'Сумерки удобны: достаточно света, чтобы видеть проблему, и достаточно тьмы, чтобы проблема не сразу увидела вас.'
    when 'subclass:cleric:war-domain' then 'Редкий жрец, который честно признаёт: иногда богословский спор заканчивается оружием. Экономит время.'
    else 'Заклинания домена всегда под рукой. Небеса, похоже, тоже любят держать аварийный набор поближе.'
  end;
$$;

create or replace function private.cleric_group_voss(p_mechanics jsonb,p_catalog_key text,p_level integer)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_agg(
    case
      when m->>'sourceKey'='subclass-spells' then
        jsonb_set(m,'{presentation}',coalesce(m->'presentation','{}'::jsonb)||jsonb_build_object('authorComment',private.cleric_domain_voss(p_catalog_key)),true)
      when p_catalog_key='class:cleric' and m->>'sourceKey'='channel-divinity' and m->>'type'='resource' then
        jsonb_set(m,'{presentation}',coalesce(m->'presentation','{}'::jsonb)||jsonb_build_object('authorComment',case when p_level>=18 then 'Запас чудес вырос. Обычно вместе с ним растёт и уверенность жреца, что план больше не нужен.' else 'Больше Божественного канала — больше способов убедить окружающих, что небеса лично одобрили происходящее.' end),true)
      else m
    end order by ord
  ),'[]'::jsonb)
  from jsonb_array_elements(coalesce(p_mechanics,'[]'::jsonb)) with ordinality q(m,ord);
$$;

create or replace function private.cleric_template_group_voss(p_mechanics jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_agg(
    case when m->>'sourceKey' in ('armor-light','armor-medium','armor-shield','saving-throw-charisma','saving-throw-wisdom','weapon-simple') then
      jsonb_set(m,'{presentation}',coalesce(m->'presentation','{}'::jsonb)||jsonb_build_object('authorComment',case m->>'sourceKey'
        when 'armor-light' then 'Лёгкая броня хороша тем, что в ней можно быстро уйти от последствий собственной веры.'
        when 'armor-medium' then 'Средняя броня — компромисс между «я доверяю богу» и «но металл всё же надену».'
        when 'armor-shield' then 'Щит — редкий священный символ, который работает даже у атеиста.'
        when 'saving-throw-charisma' then 'Умение не дать миру переписать вашу личность полезно. Особенно рядом с людьми, которые называют это обращением в веру.'
        when 'saving-throw-wisdom' then 'Здравый смысл у жреца считается профессиональным навыком. Удивительно строгий отбор.'
        else 'Простое оружие не требует откровения. Берёте правильным концом и убеждаете ближнего.' end),true)
      else m end order by ord
  ),'[]'::jsonb)
  from jsonb_array_elements(coalesce(p_mechanics,'[]'::jsonb)) with ordinality q(m,ord);
$$;

create or replace function private.apply_cleric_text_ready(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  p record;
  v_cleric uuid;
begin
  select id into v_cleric from public.rule_templates
  where campaign_id=p_campaign_id and is_active and catalog_key='class:cleric'
  order by version desc limit 1;
  if v_cleric is null then return; end if;

  for p in select * from (values
    ('class:cleric',1,'hit-die','Кость здоровья: к8',$r$Кость здоровья Жреца — к8. На 1 уровне максимум HP увеличивается на 8 + модификатор Телосложения; на каждом следующем уровне Жреца — на 1к8 + модификатор Телосложения либо на фиксированное среднее значение кости по правилам повышения уровня.$r$),
    ('class:cleric',1,'divine-order','Божественный сан',$r$На 1 уровне выберите один Божественный сан; выбор сохраняется. Защитник даёт владение воинским оружием и тяжёлой бронёй. Чудотворец даёт ещё один заговор Жреца и позволяет добавлять модификатор Мудрости, минимум +1, к проверкам Интеллекта (Магия) и Интеллекта (Религия).$r$),
    ('class:cleric',1,'spellcasting','Заклинания',$r$Мудрость — заклинательная характеристика Жреца. Сл спасброска от ваших заклинаний Жреца = 8 + бонус мастерства + модификатор Мудрости; модификатор атаки заклинанием = бонус мастерства + модификатор Мудрости. Священный символ можно использовать как заклинательную фокусировку. Вы знаете 3 заговора на уровнях Жреца 1–3, 4 заговора на уровнях 4–9 и 5 заговоров с 10 уровня. Число подготовленных заклинаний Жреца по уровням 1–20: 4, 5, 6, 7, 9, 10, 11, 12, 14, 15, 16, 16, 17, 17, 18, 18, 19, 20, 21, 22. Подготавливайте только заклинания тех уровней, для которых у вас есть ячейки. После долгого отдыха можно заменить любое число подготовленных заклинаний другими заклинаниями Жреца. Прогрессия ячеек по уровням Жреца 1–20: 2; 3; 4/2; 4/3; 4/3/2; 4/3/3; 4/3/3/1; 4/3/3/2; 4/3/3/3/1; 4/3/3/3/2; 4/3/3/3/2/1; 4/3/3/3/2/1; 4/3/3/3/2/1/1; 4/3/3/3/2/1/1; 4/3/3/3/2/1/1/1; 4/3/3/3/2/1/1/1; 4/3/3/3/2/1/1/1/1; 4/3/3/3/3/1/1/1/1; 4/3/3/3/3/2/1/1/1; 4/3/3/3/3/2/2/1/1. Числа в каждой строке идут от ячеек 1 уровня к наивысшему доступному. Чтобы сотворить подготовленное заклинание 1 уровня или выше, потратьте ячейку не ниже уровня заклинания. Все потраченные ячейки восстанавливаются после долгого отдыха. Заклинания, которые класс или домен держит подготовленными постоянно, не занимают обычный лимит подготовки.$r$),
    ('class:cleric',2,'channel-divinity','Божественный канал',$r$Божественный канал имеет общий запас: 2 использования на 2 уровне Жреца, 3 на 6 и 4 на 18. После короткого отдыха возвращается 1 потраченное использование, после долгого — весь запас. Если эффект Божественного канала требует спасбросок, используется Сл заклинаний Жреца. На 2 уровне доступны два способа расхода. «Божественная искра»: магическим действием потратьте 1 использование, выберите другое видимое существо в 30 футах и бросьте 1к8 + модификатор Мудрости; либо восстановите цели столько HP, либо заставьте её совершить спасбросок Телосложения: при провале она получает столько некротического или сияющего урона на ваш выбор, при успехе — половину, округляя вниз. Кость Искры становится 2к8 на 7 уровне, 3к8 на 13 и 4к8 на 18. «Изгнание нежити»: магическим действием потратьте 1 использование; каждая выбранная вами нежить в 30 футах совершает спасбросок Мудрости. При провале она Испугана и Недееспособна на 1 минуту и в свои ходы старается удалиться от вас как можно дальше. Для конкретной цели эффект заканчивается раньше, если она получает урон; весь эффект также прекращается, если вы становитесь Недееспособны или умираете.$r$),
    ('class:cleric',3,'cleric-subclass','Домен Жреца',$r$На 3 уровне выберите один домен Жреца. Вы сразу получаете все способности выбранного домена, доступные к 3 уровню. На последующих указанных в прогрессии домена уровнях вы автоматически получаете его новые способности; повторно выбирать домен не нужно.$r$),
    ('class:cleric',4,'ability-score-improvement','Улучшение характеристик',$r$Получите талант «Улучшение характеристик» или другой талант, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20. Жрец получает эту возможность на 4, 8, 12 и 16 уровнях.$r$),
    ('class:cleric',5,'sear-undead','Испепеление нежити',$r$Когда используете Изгнание нежити, бросьте число к8, равное модификатору Мудрости, минимум 1к8. Каждая нежить, провалившая спасбросок против этого Изгнания, получает сияющий урон, равный общей сумме броска. Этот урон не прекращает эффект Изгнания нежити.$r$),
    ('class:cleric',6,'subclass','Способность домена',$r$На этом уровне выбранный домен Жреца даёт следующую способность своей прогрессии. Используйте полное правило этой способности в карточке домена; новый домен не выбирается.$r$),
    ('class:cleric',7,'blessed-strikes','Благословенные удары',$r$На 7 уровне один раз выберите один вариант. «Божественный удар»: один раз на каждом своём ходу после попадания атакой оружием добавьте 1к8 некротического или сияющего урона, выбирая тип при попадании. «Могущественные заклинания»: к урону любого заговора Жреца добавляйте модификатор Мудрости. На 14 уровне автоматически усиливается именно выбранный вариант; нового выбора не происходит.$r$),
    ('class:cleric',8,'ability-score-improvement','Улучшение характеристик',$r$Получите талант «Улучшение характеристик» или другой талант, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20. Жрец получает эту возможность на 4, 8, 12 и 16 уровнях.$r$),
    ('class:cleric',10,'divine-intervention','Божественное вмешательство',$r$Магическим действием выберите заклинание Жреца 5 уровня или ниже, время накладывания которого не является реакцией. Сотворите выбранное заклинание частью того же действия без траты ячейки и без материальных компонентов. После применения Божественное вмешательство недоступно до окончания долгого отдыха.$r$),
    ('class:cleric',12,'ability-score-improvement','Улучшение характеристик',$r$Получите талант «Улучшение характеристик» или другой талант, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20. Жрец получает эту возможность на 4, 8, 12 и 16 уровнях.$r$),
    ('class:cleric',14,'improved-blessed-strikes','Улучшенные благословенные удары',$r$Автоматически усиливается вариант Благословенных ударов, выбранный на 7 уровне. Божественный удар увеличивает дополнительный урон с 1к8 до 2к8. Могущественные заклинания сохраняют добавление модификатора Мудрости к урону заговора; кроме того, когда ваш заговор Жреца наносит урон, можете дать себе или существу в пределах 60 футов временные HP, равные удвоенному модификатору Мудрости.$r$),
    ('class:cleric',16,'ability-score-improvement','Улучшение характеристик',$r$Получите талант «Улучшение характеристик» или другой талант, требованиям которого соответствуете. Если выбран «Улучшение характеристик», увеличьте одну характеристику на 2 либо две характеристики на 1; этим талантом нельзя поднять характеристику выше 20. Жрец получает эту возможность на 4, 8, 12 и 16 уровнях.$r$),
    ('class:cleric',17,'subclass','Способность домена',$r$На этом уровне выбранный домен Жреца даёт следующую способность своей прогрессии. Используйте полное правило этой способности в карточке домена; новый домен не выбирается.$r$),
    ('class:cleric',19,'epic-boon','Эпический дар',$r$На 19 уровне получите один талант категории «Эпический дар» или другой талант, требованиям которого соответствуете. Выбранный талант действует по своему полному правилу и не расходует отдельный ресурс Жреца, если сам талант не говорит обратного.$r$),
    ('class:cleric',20,'greater-divine-intervention','Высшее божественное вмешательство',$r$При использовании Божественного вмешательства можете выбрать «Исполнение желаний» как вызываемое заклинание. Если выбрали именно его, после завершения применения Божественное вмешательство недоступно до окончания 2к4 долгих отдыхов вместо обычного восстановления после одного долгого отдыха.$r$),

    ('subclass:cleric:arcana-domain',1,'arcana-domain-l1-1','Посвящённый в магию',$r$Вы получаете владение навыком Магия и выбираете 2 заговора из списка Волшебника. Для вас эти заговоры считаются заговорами Жреца и используют Мудрость как заклинательную характеристику. Заклинания домена, выдаваемые прогрессией подкласса, всегда считаются подготовленными и не занимают число обычных подготовленных заклинаний.$r$),
    ('subclass:cleric:arcana-domain',2,'channel-divinity-arcane-abjuration-l2-1','Магическое изгнание',$r$Действием потратьте 1 использование Божественного канала и выберите одного небожителя, элементаля, фею или исчадие в пределах 30 футов, которое видите. Цель совершает спасбросок Мудрости против Сл заклинаний Жреца. При провале она изгнана вашим священным запретом на 1 минуту или пока не получит урон: она старается удалиться от вас, не может добровольно приблизиться к вам, не совершает реакции и обычно тратит действие на Рывок либо попытку освободиться от удерживающего эффекта; если двигаться некуда, использует Уклонение. С 5 уровня, если КО цели не выше текущего порога Уничтожения нежити Жреца, провал вместо обычного изгнания отправляет её на родной план на 1 минуту, если она не находится там изначально.$r$),
    ('subclass:cleric:arcana-domain',6,'spell-breaker-l6-1','Разрушитель чар',$r$Когда заклинанием 1 уровня или выше восстанавливаете HP союзнику, можете одновременно закончить на нём одно заклинание по своему выбору. Уровень снимаемого заклинания должен быть не выше уровня ячейки, потраченной на лечащее заклинание. Отдельного действия или ресурса не требуется.$r$),
    ('subclass:cleric:arcana-domain',8,'potent-spellcasting-l8-1','Могущественные заклинания',$r$Когда заговор Жреца наносит урон, добавьте модификатор Мудрости к одному броску урона этого заговора. Это пассивный эффект и не расходует ресурс.$r$),
    ('subclass:cleric:arcana-domain',8,'blessed-strikes-l8-2','Благословенные удары',$r$Если этот вариант выбран вместо другого боевого усиления домена, один раз на каждом своём ходу, когда вы попадаете атакой оружием или наносите урон заговором Жреца, можете нанести одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится; ограничение — один раз за ваш ход.$r$),
    ('subclass:cleric:arcana-domain',17,'arcane-mastery-l17-1','Мастер тайной магии',$r$Выберите по одному заклинанию Волшебника 6, 7, 8 и 9 уровня. Выбранные заклинания становятся для вас заклинаниями домена Жреца: они всегда подготовлены, используют Мудрость и ячейки Жреца обычным способом. Выбор совершается при получении способности; сама способность не создаёт дополнительных ячеек.$r$),

    ('subclass:cleric:death-domain',1,'death-domain-l1-1','Жнец',$r$Вы получаете владение воинским оружием и изучаете один заговор школы Некромантии из любого списка заклинаний; для вас он считается заговором Жреца. Когда вы накладываете заговор Некромантии, который обычно выбирает только одно существо, можете вместо этого выбрать двух существ, если они находятся не дальше 5 футов друг от друга и обе цели находятся в обычной дальности заговора.$r$),
    ('subclass:cleric:death-domain',2,'channel-divinity-touch-of-death-l2-1','Касание смерти',$r$Когда попадаете по существу рукопашной атакой, можете потратить 1 использование Божественного канала сразу после попадания. Цель получает дополнительный некротический урон, равный 5 + удвоенный уровень Жреца. Спасброска нет; ресурс расходуется на сработавшее попадание.$r$),
    ('subclass:cleric:death-domain',6,'inescapable-destruction-l6-1','Неизбежное разрушение',$r$Некротический урон ваших заклинаний Жреца и способностей Божественного канала игнорирует сопротивление некротическому урону. Иммунитет эта способность не снимает. Эффект пассивный.$r$),
    ('subclass:cleric:death-domain',8,'divine-strike-l8-1','Божественный удар',$r$Один раз на каждом своём ходу, когда попадаете атакой оружием, можете добавить к урону этой атаки 1к8 некротического урона. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$),
    ('subclass:cleric:death-domain',8,'blessed-strikes-l8-2','Благословенные удары',$r$Если этот вариант выбран вместо другого боевого усиления домена, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Отдельного ресурса нет.$r$),
    ('subclass:cleric:death-domain',17,'improved-reaper-l17-1','Улучшенный жнец',$r$Когда накладываете заклинание Некромантии 1–5 уровня, которое обычно выбирает только одно существо, можете выбрать второе существо в пределах дальности заклинания, если обе цели находятся не дальше 5 футов друг от друга. Если заклинание расходует материальный компонент, необходимо предоставить такой компонент для каждой цели. Ячейка заклинания тратится одна.$r$),

    ('subclass:cleric:forge-domain',1,'forge-domain-l1-1','Благословение кузни',$r$Вы получаете владение тяжёлой бронёй и инструментами кузнеца. После долгого отдыха выберите один немагический доспех либо одно немагическое простое или воинское оружие, которого касаетесь. До следующего долгого отдыха или вашей смерти предмет становится магическим: доспех получает +1 к КД, а оружие — +1 к броскам атаки и урона. Одновременно так может быть усилен только один предмет.$r$),
    ('subclass:cleric:forge-domain',2,'channel-divinity-artisan-s-blessing-l2-1','Благословение ремесленника',$r$Потратьте 1 использование Божественного канала и проведите непрерывный часовой ритуал, выкладывая металл стоимостью, равной создаваемому предмету. В конце ритуала создайте один простой металлический предмет стоимостью не более 100 зм; это может быть оружие, доспех, боеприпасы, инструмент или другой предмет, если в нём есть необходимое количество металла. Можно воссоздать металлическую копию существующего предмета, если его стоимость не выше 100 зм. Использованный металл расходуется.$r$),
    ('subclass:cleric:forge-domain',6,'soul-of-the-forge-l6-1','Душа кузни',$r$Вы получаете сопротивление урону огнём. Пока носите тяжёлую броню, ваш КД дополнительно увеличивается на 1. Оба эффекта пассивны и не требуют ресурса.$r$),
    ('subclass:cleric:forge-domain',8,'divine-strike-l8-1','Божественный удар',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 урона огнём. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$),
    ('subclass:cleric:forge-domain',8,'blessed-strikes-l8-2','Благословенные удары',$r$Если выбран этот альтернативный вариант усиления, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$),
    ('subclass:cleric:forge-domain',17,'saint-of-forge-and-fire-l17-1','Святой кузни и огня',$r$Вы получаете иммунитет к урону огнём. Кроме того, пока носите тяжёлую броню, получаете сопротивление дробящему, колющему и рубящему урону от немагических атак. Эффекты пассивны.$r$),

    ('subclass:cleric:grave-domain',3,'grave-domain-l3-1','Зов смерти, Возвращение к жизни и Путь к могиле',$r$Вы получаете три связанных правила. «Зов смерти»: один раз за ход, когда заклинанием или атакой наносите урон существу, у которого уже не все HP, оно получает ещё 1к4 некротического урона; с 11 уровня — 1к6. «Возвращение к жизни»: «Уход за умирающим» можно накладывать бонусным действием; если заклинанием или Божественным каналом лечите существо с 0 HP, вместо бросков костей лечения берите максимальный результат каждой кости. «Путь к могиле»: бонусным действием потратьте 1 Божественный канал и прокляните видимое существо в 30 футах до начала вашего следующего хода; у него помеха на атаки и спасброски. Когда вы или видимый вами союзник попадает по проклятой цели атакой, можете без действия закончить проклятие и добавить к этой атаке некротический или сияющий урон, равный уровню Жреца.$r$),
    ('subclass:cleric:grave-domain',6,'sentinel-at-death-s-door-l6-1','Страж у врат смерти',$r$Когда вы или окровавленное существо, которое видите в пределах 60 футов, получает попадание атакой, можете реакцией уменьшить урон этой атаки вдвое, округляя вниз. Если попадание было критическим, все дополнительные эффекты, зависящие именно от критического попадания, отменяются. Использований равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха.$r$),
    ('subclass:cleric:grave-domain',17,'divine-reaper-l17-1','Божественный жнец',$r$Способность даёт два эффекта. «Усиленная некромантия»: когда накладываете заклинание Некромантии 5 уровня или ниже, выбирающее одну цель, либо заклинание из списка домена Могилы, можете потратить 1 Божественный канал и выбрать вторую цель в дальности заклинания; дорогие или расходуемые материальные компоненты нужны отдельно для каждой цели. «Хранитель душ»: когда враг умирает в 60 футах от вас и вы не Недееспособны, вы или видимое существо в 60 футах восстанавливает HP, равные удвоенному уровню Жреца. После этого Хранитель душ возвращается после короткого или долгого отдыха; можно без действия восстановить его раньше, потратив ячейку 6 уровня или выше.$r$),

    ('subclass:cleric:knowledge-domain',3,'knowledge-domain-l3-1','Знания и Магия разума',$r$Вы получаете владение одним видом ремесленных инструментов и выбираете 2 навыка из Магии, Истории, Природы и Религии; в этих двух навыках получаете Экспертизу. Кроме того, «Магия разума» позволяет магическим действием потратить 1 использование Божественного канала, выбрать подготовленное заклинание школы Прорицания из списка заклинаний домена Знания и сотворить его частью того же действия без ячейки и без материальных компонентов.$r$),
    ('subclass:cleric:knowledge-domain',6,'unfettered-mind-l6-1','Свободный разум',$r$Вы получаете телепатию на 60 футов и при её использовании можете одновременно связаться с числом существ до модификатора Мудрости, минимум 1. Также получаете владение спасбросками Интеллекта; если уже владеете ими, выберите другой спасбросок, которым ещё не владеете, и получите владение им. Ресурс не тратится.$r$),
    ('subclass:cleric:knowledge-domain',17,'divine-foreknowledge-l17-1','Божественное предвидение',$r$Бонусным действием активируйте божественное предвидение на 1 час. Всё это время у вас преимущество на все испытания к20: атаки, проверки характеристик и спасброски. После применения способность недоступна до долгого отдыха. Без действия можно восстановить её использование раньше, потратив ячейку заклинания 6 уровня или выше.$r$),

    ('subclass:cleric:life-domain',3,'disciple-of-life','Ученик жизни',$r$Когда заклинание, сотворённое с тратой ячейки, восстанавливает существу HP, в ход сотворения эта цель дополнительно восстанавливает HP в количестве 2 + уровень потраченной ячейки.$r$),
    ('subclass:cleric:life-domain',3,'preserve-life','Сохранить жизнь',$r$Магическим действием потратьте 1 использование Божественного канала. Выберите любое число окровавленных существ в 30 футах, включая себя. Получите общий запас лечения, равный 5 × уровень Жреца, и распределите его между выбранными целями. Ни одну цель нельзя этим лечением поднять выше половины её максимума HP.$r$),
    ('subclass:cleric:life-domain',6,'blessed-healer','Благословенный целитель',$r$Сразу после того, как вы сотворили с тратой ячейки заклинание, восстановившее HP хотя бы одному существу кроме вас, вы восстанавливаете себе HP в количестве 2 + уровень потраченной ячейки.$r$),
    ('subclass:cleric:life-domain',17,'supreme-healing','Высшее исцеление',$r$Когда ваше заклинание или Божественный канал должен бросить одну или несколько костей для восстановления HP, кости лечения не бросаются: каждая считается выпавшей на максимальное значение. Например, 2к6 лечения дают 12 HP до применения остальных модификаторов.$r$),

    ('subclass:cleric:light-domain',3,'light-domain-l3-1','Сияние рассвета и Защитная вспышка',$r$На 3 уровне домен даёт два активных правила. «Сияние рассвета»: магическим действием потратьте 1 Божественный канал; вся магическая Тьма в 30-футовой эманации от вас рассеивается, а каждое выбранное вами существо в этой области совершает спасбросок Телосложения. При провале оно получает 2к10 + уровень Жреца сияющего урона, при успехе — половину. «Защитная вспышка»: когда видимое вами существо в 30 футах совершает атаку, можете реакцией дать этой атаке помеху до определения попадания. Использований Вспышки равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха.$r$),
    ('subclass:cleric:light-domain',6,'improved-warding-flare-l6-1','Улучшенная защитная вспышка',$r$Все использования Защитной вспышки теперь возвращаются после короткого или долгого отдыха. Кроме того, каждый раз, когда используете Защитную вспышку, можете дать цели спровоцировавшей атаки временные HP, равные 2к6 + модификатор Мудрости. Дополнительного действия или ресурса не требуется.$r$),
    ('subclass:cleric:light-domain',17,'corona-of-light-l17-1','Корона света',$r$Магическим действием создайте вокруг себя ауру солнечного света на 1 минуту; её можно прекратить без действия. Вы излучаете яркий свет на 60 футов и тусклый ещё на 30. Враги в области яркого света совершают с помехой спасброски против вашего Сияния рассвета и против ваших заклинаний, наносящих урон огнём или сиянием. Использований равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха.$r$),

    ('subclass:cleric:nature-domain',1,'nature-domain-l1-1','Ученик природы',$r$Вы изучаете один заговор Друида; для вас он считается заговором Жреца и использует Мудрость. Также получаете владение одним навыком на выбор: Уход за животными, Природа или Выживание, и владение тяжёлой бронёй. Эти эффекты постоянны.$r$),
    ('subclass:cleric:nature-domain',2,'channel-divinity-charm-animals-and-plants-l2-1','Очарование животных и растений',$r$Действием потратьте 1 Божественный канал. Каждый зверь или растение в пределах 30 футов, которое видит вас, совершает спасбросок Мудрости против Сл заклинаний Жреца. При провале существо очаровано вами на 1 минуту либо пока не получит урон. Каждая цель бросает отдельно.$r$),
    ('subclass:cleric:nature-domain',6,'dampen-elements-l6-1','Сдерживание стихий',$r$Когда вы или существо в пределах 30 футов получает урон кислотой, холодом, огнём, электричеством или громом, можете реакцией дать этой цели сопротивление именно к этому срабатыванию урона. Сопротивление применяется до расчёта окончательного урона и заканчивается сразу после него. Ресурс не тратится.$r$),
    ('subclass:cleric:nature-domain',8,'divine-strike-l8-1','Божественный удар',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 урона холодом, огнём или электричеством на выбор. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$),
    ('subclass:cleric:nature-domain',8,'blessed-strikes-l8-2','Благословенные удары',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$),
    ('subclass:cleric:nature-domain',17,'master-of-nature-l17-1','Владыка природы',$r$Пока существа остаются очарованы вашим «Очарованием животных и растений», бонусным действием можете дать устную команду каждому из них, определив, что оно будет делать в свой следующий ход. Команда не требует отдельного спасброска, но само очарование по-прежнему заканчивается по своим обычным условиям.$r$),

    ('subclass:cleric:order-domain',1,'order-domain-l1-1','Глас власти',$r$Вы получаете владение тяжёлой бронёй и одним навыком на выбор: Запугивание или Убеждение. «Глас власти»: когда заклинанием 1 уровня или выше тратите ячейку и выбираете целью союзника, один союзник, затронутый этим заклинанием, может сразу после заклинания реакцией совершить одну атаку оружием по существу по вашему выбору, которое вы видите. Если заклинание затронуло нескольких союзников, реакцию получает только один из них.$r$),
    ('subclass:cleric:order-domain',2,'channel-divinity-order-s-demand-l2-1','Требование порядка',$r$Действием потратьте 1 Божественный канал. Каждое выбранное вами существо в 30 футах, которое видит или слышит вас, совершает спасбросок Мудрости. При провале оно очаровано вами до конца вашего следующего хода либо пока не получит урон. В момент провала можете также потребовать, чтобы цель немедленно уронила всё, что держит.$r$),
    ('subclass:cleric:order-domain',6,'embodiment-of-the-law-l6-1','Воплощение закона',$r$Когда накладываете заклинание школы Очарования с обычным временем накладывания «действие», можете вместо действия наложить его бонусным действием. Использований равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха. Ячейка и другие компоненты заклинания расходуются как обычно.$r$),
    ('subclass:cleric:order-domain',8,'divine-strike-l8-1','Божественный удар',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 психического урона. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$),
    ('subclass:cleric:order-domain',8,'blessed-strikes-l8-2','Благословенные удары',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$),
    ('subclass:cleric:order-domain',17,'order-s-wrath-l17-1','Гнев порядка',$r$Когда наносите существу дополнительный психический урон Божественным ударом, пометьте его до начала вашего следующего хода. Следующий союзник, который до этого момента попадёт по помеченной цели атакой, наносит ей дополнительно 2к8 психического урона, после чего метка заканчивается. На одной цели одновременно учитывается только ближайшее такое срабатывание.$r$),

    ('subclass:cleric:peace-domain',1,'peace-domain-l1-1','Ободряющая связь',$r$Вы получаете владение одним навыком на выбор: Проницательность, Выступление или Убеждение. «Ободряющая связь»: действием выберите число согласных существ в пределах 30 футов до вашего бонуса мастерства, включая себя. Связь длится 10 минут или пока не используете способность снова. Пока связанное существо находится в 30 футах хотя бы от одного другого связанного существа, один раз за ход оно может добавить 1к4 к атаке, проверке характеристики или спасброску после броска к20. Использований Связи равно бонусу мастерства; весь запас возвращается после долгого отдыха.$r$),
    ('subclass:cleric:peace-domain',2,'channel-divinity-balm-of-peace-l2-1','Бальзам мира',$r$Действием потратьте 1 Божественный канал и переместитесь на расстояние до своей Скорости, не провоцируя атаки по возможности. Во время этого перемещения, когда впервые проходите в пределах 5 футов от существа, можете восстановить ему 2к6 + модификатор Мудрости HP. Одно и то же существо можно вылечить этим применением только один раз.$r$),
    ('subclass:cleric:peace-domain',6,'protective-bond-l6-1','Защитная связь',$r$Когда существо, связанное вашей Ободряющей связью, собирается получить урон, другое связанное существо в пределах 30 футов от него может реакцией телепортироваться в свободное место в 5 футах от первой цели. Телепортировавшееся существо получает весь спровоцировавший урон вместо первоначальной цели. Связь должна быть активна; дополнительный ресурс не тратится.$r$),
    ('subclass:cleric:peace-domain',8,'potent-spellcasting-l8-1','Могущественные заклинания',$r$Когда заговор Жреца наносит урон, добавьте модификатор Мудрости к одному броску урона этого заговора. Эффект пассивный.$r$),
    ('subclass:cleric:peace-domain',8,'blessed-strikes-l8-2','Благословенные удары',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$),
    ('subclass:cleric:peace-domain',17,'expansive-bond-l17-1','Расширенная связь',$r$Дальность Защитной связи увеличивается с 30 до 60 футов. Когда связанное существо телепортируется реакцией Защитной связи и принимает чужой урон, оно получает сопротивление всему урону до конца текущего хода, включая спровоцировавший урон. Остальные условия Ободряющей и Защитной связи не меняются.$r$),

    ('subclass:cleric:tempest-domain',1,'tempest-domain-l1-1','Гнев бури',$r$Вы получаете владение воинским оружием и тяжёлой бронёй. «Гнев бури»: когда видимое вами существо в пределах 5 футов попадает по вам атакой, можете реакцией заставить его совершить спасбросок Ловкости. При провале оно получает 2к8 урона электричеством или громом на ваш выбор, при успехе — половину. Использований равно модификатору Мудрости, минимум 1; весь запас возвращается после долгого отдыха.$r$),
    ('subclass:cleric:tempest-domain',2,'channel-divinity-destructive-wrath-l2-1','Разрушительный гнев',$r$Когда должны бросить кости урона электричеством или громом, можете потратить 1 использование Божественного канала и вместо броска взять максимально возможный результат каждой кости этого урона. Способность не добавляет новых костей и не меняет тип урона; она только максимизирует уже определённые кости.$r$),
    ('subclass:cleric:tempest-domain',6,'thunderbolt-strike-l6-1','Громовой удар',$r$Когда наносите существу Большого размера или меньше урон электричеством, можете оттолкнуть его от себя на расстояние до 10 футов. Спасброска и ресурса нет; вы сами выбираете, применять ли отталкивание.$r$),
    ('subclass:cleric:tempest-domain',8,'divine-strike-l8-1','Божественный удар',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 урона громом. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$),
    ('subclass:cleric:tempest-domain',8,'blessed-strikes-l8-2','Благословенные удары',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$),
    ('subclass:cleric:tempest-domain',17,'stormborn-l17-1','Рождённый бурей',$r$Пока вы не находитесь под землёй и не внутри помещения, получаете Скорость полёта, равную текущей Скорости ходьбы. Полёт не требует действия или ресурса и прекращается, когда перестаёт выполняться условие местности.$r$),

    ('subclass:cleric:trickery-domain',3,'trickery-domain-l3-1','Благословение обманщика и Вызов двойника',$r$На 3 уровне получаете два правила. «Благословение обманщика»: магическим действием выберите себя или согласное существо в 30 футах; до вашего следующего долгого отдыха либо до следующего использования этого умения цель имеет преимущество на проверки Ловкости (Скрытность). «Вызов двойника»: бонусным действием потратьте 1 Божественный канал и создайте неосязаемую визуальную копию себя в видимом свободном месте в 30 футах. Она существует 1 минуту, пока вы не уберёте её без действия или не станете Недееспособны. Заклинания можно накладывать так, словно вы находитесь в пространстве копии, но используются ваши чувства. Если вы и копия одновременно в 5 футах от существа, которое видит копию, ваши атаки по нему имеют преимущество. Бонусным действием копию можно передвинуть до 30 футов в видимое свободное место, остающееся в 120 футах от вас.$r$),
    ('subclass:cleric:trickery-domain',6,'trickster-s-transposition-l6-1','Перестановка обманщика',$r$Каждый раз, когда бонусным действием создаёте копию через Вызов двойника или передвигаете уже существующую копию, можете в рамках того же бонусного действия телепортироваться, поменявшись с ней местами. Дополнительное использование Божественного канала при обычном перемещении уже созданной копии не тратится.$r$),
    ('subclass:cleric:trickery-domain',17,'improved-duplicity-l17-1','Улучшенная двойственность',$r$Вызов двойника получает два улучшения. «Общее отвлечение»: вы и ваши союзники совершаете с преимуществом атаки по существу, находящемуся в пределах 5 футов от копии. «Исцеляющая иллюзия»: когда копия заканчивает существование, выберите себя или существо в пределах 5 футов от неё; выбранная цель восстанавливает HP, равные вашему уровню Жреца.$r$),

    ('subclass:cleric:twilight-domain',1,'twilight-domain-l1-1','Глаза ночи и Бдительное благословение',$r$Вы получаете владение воинским оружием и тяжёлой бронёй. Ваше тёмное зрение имеет дальность 300 футов. Действием можете поделиться этим тёмным зрением на 1 час с числом согласных существ до модификатора Мудрости, минимум 1, которые находятся в 10 футах от вас в момент применения; повторно бесплатно это можно сделать после долгого отдыха либо раньше, потратив ячейку заклинания. Кроме того, действием можете коснуться существа, включая себя, и дать ему преимущество на следующий бросок инициативы; благословение заканчивается после этого броска или когда вы дадите его другой цели.$r$),
    ('subclass:cleric:twilight-domain',2,'channel-divinity-twilight-sanctuary-l2-1','Сумеречное святилище',$r$Действием потратьте 1 Божественный канал и создайте вокруг себя 30-футовую сферу тусклого света на 1 минуту; сфера движется вместе с вами и заканчивается, если вы Недееспособны или умираете. Когда существо, включая вас, заканчивает ход внутри сферы, можете выбрать один эффект для него: дать временные HP, равные 1к6 + уровень Жреца, либо закончить на нём состояние Очарован или Испуган. Для каждого существа решение принимается в конце его хода.$r$),
    ('subclass:cleric:twilight-domain',6,'steps-of-night-l6-1','Шаги ночи',$r$Пока находитесь в тусклом свете или темноте, бонусным действием можете получить Скорость полёта, равную Скорости ходьбы, на 1 минуту. Использований равно бонусу мастерства; весь запас возвращается после долгого отдыха. Если условия освещения меняются после активации, уже полученный полёт продолжается до конца длительности.$r$),
    ('subclass:cleric:twilight-domain',8,'divine-strike-l8-1','Божественный удар',$r$Один раз на каждом своём ходу после попадания атакой оружием можете добавить 1к8 сияющего урона. С 14 уровня дополнительный урон становится 2к8. Ресурс не тратится.$r$),
    ('subclass:cleric:twilight-domain',8,'blessed-strikes-l8-2','Благословенные удары',$r$Если выбран этот альтернативный вариант, один раз на каждом своём ходу после попадания оружием или нанесения урона заговором Жреца нанесите одной цели дополнительно 1к8 сияющего урона. Ресурс не тратится.$r$),
    ('subclass:cleric:twilight-domain',17,'twilight-shroud-l17-1','Сумеречный покров',$r$Пока активно ваше Сумеречное святилище, вы и союзники внутри его сферы имеете половинное укрытие: +2 к КД и спасброскам Ловкости против эффектов, для которых укрытие применимо. Дополнительного действия или ресурса не требуется.$r$),

    ('subclass:cleric:war-domain',3,'war-domain-l3-1','Направленный удар и Жрец войны',$r$На 3 уровне получаете два боевых правила. «Направленный удар»: когда вы или существо в 30 футах промахивается атакой, можете потратить 1 Божественный канал и дать этому броску +10, после чего ГМ заново проверяет попадание; если помогаете другому существу, дополнительно тратите реакцию, для собственной атаки реакция не нужна. «Жрец войны»: бонусным действием совершите одну атаку оружием или Безоружный удар. Использований Жреца войны равно модификатору Мудрости, минимум 1; весь запас возвращается после короткого или долгого отдыха.$r$),
    ('subclass:cleric:war-domain',6,'war-god-s-blessing-l6-1','Благословение бога войны',$r$Вместо траты ячейки можете потратить 1 использование Божественного канала, чтобы сотворить «Щит веры» или «Духовное оружие». Заклинание, сотворённое так, не требует Концентрации и длится 1 минуту; оно заканчивается раньше, если вы снова сотворите то же заклинание, станете Недееспособны или умрёте. Все остальные параметры заклинания действуют обычно.$r$),
    ('subclass:cleric:war-domain',17,'avatar-of-battle-l17-1','Аватар битвы',$r$Вы постоянно имеете сопротивление дробящему, колющему и рубящему урону независимо от того, магический источник урона или нет. Действие и ресурс не требуются.$r$)
  ) as q(catalog_key,level,source_key,label,description)
  loop
    perform private.cleric_patch_feature_text(p_campaign_id,p.catalog_key,p.level,p.source_key,p.label,p.description);
  end loop;

  update public.rule_templates t
  set mechanical_summary=v.summary,
      author_description=v.description,
      author_comment=v.voss,
      rules_meta=coalesce(t.rules_meta,'{}'::jsonb)||jsonb_build_object('class_work_status',jsonb_build_object('text','READY','mechanics','NOT_AUDITED'),'text_closure','2026-08-29-cleric-ready','feature_author','Рейнар Восс'),
      updated_at=now()
  from (values
    ('class:cleric',$r$Подготовленный полный заклинатель на Мудрости: заговоры, подготовленные заклинания и ячейки растут по уровням; Божественный канал имеет общий запас, а выбранный домен добавляет собственные правила и постоянно подготовленные заклинания.$r$,$r$Жрец владеет божественной магией, готовит набор заклинаний после отдыха и направляет силу через Божественный канал. Домен определяет специализацию: от лечения и защиты до знания, обмана, стихий или прямого боя.$r$,$r$Жрец говорит, что сила приходит свыше. Я лишь советую считать, сколько этой силы осталось, прежде чем сообщать врагу, что бог на вашей стороне.$r$),
    ('subclass:cleric:arcana-domain',$r$Соединяет божественную и тайную магию: даёт волшебные заговоры, изгнание сверхъестественных существ, снятие чар через лечение и поздний доступ к высокоуровневым заклинаниям Волшебника.$r$,$r$Домен Магии изучает тайные практики рядом с обычной божественной подготовкой. Его способности расширяют набор магических инструментов Жреца и позволяют бороться с чужой магией напрямую.$r$,private.cleric_domain_voss('subclass:cleric:arcana-domain')),
    ('subclass:cleric:death-domain',$r$Некромантия, дополнительный некротический урон, игнорирование сопротивления некрозу и возможность поражать второй целью одноцелевые некромантические заклинания.$r$,$r$Домен Смерти сосредоточен на некромантии и прямом причинении некротического урона. Он усиливает одноцелевые заклинания, рукопашные удары и позднее позволяет обходить сопротивление некрозу.$r$,private.cleric_domain_voss('subclass:cleric:death-domain')),
    ('subclass:cleric:forge-domain',$r$Тяжёлая броня, благословение оружия и доспехов, создание металлических предметов, защита от огня и усиленные удары.$r$,$r$Домен Кузни сочетает боевую защиту с властью над металлом и огнём. Он может временно усиливать снаряжение, создавать металлические предметы и со временем становится особенно устойчив к огню и физическим атакам.$r$,private.cleric_domain_voss('subclass:cleric:forge-domain')),
    ('subclass:cleric:grave-domain',$r$Контроль границы смерти: усиление против раненых, максимальное лечение целей с 0 HP, проклятие через Божественный канал, защита от критических ударов и поздний сбор душ.$r$,$r$Домен Могилы не служит смерти — он следит за тем, кто действительно должен перейти её границу. Способности домена помогают вытаскивать союзников с края, карать уже раненых врагов и вмешиваться в особенно опасные удары.$r$,private.cleric_domain_voss('subclass:cleric:grave-domain')),
    ('subclass:cleric:knowledge-domain',$r$Экспертиза и инструменты, бесплатное прорицание через Божественный канал, телепатия, защита разума и часовое божественное предвидение.$r$,$r$Домен Знания превращает информацию в прямое преимущество. Он усиливает навыки, открывает телепатию и прорицание, а на высоких уровнях позволяет заранее видеть наиболее выгодный ход событий.$r$,private.cleric_domain_voss('subclass:cleric:knowledge-domain')),
    ('subclass:cleric:life-domain',$r$Усиливает лечение заклинаниями, распределяет большой запас лечения через Божественный канал, лечит самого Жреца при помощи другим и позднее максимизирует все кости лечения.$r$,$r$Домен Жизни специализируется на восстановлении HP и спасении тяжело раненых союзников. Его способности усиливают каждую потраченную на лечение ячейку и постепенно делают результаты лечения надёжнее.$r$,private.cleric_domain_voss('subclass:cleric:life-domain')),
    ('subclass:cleric:light-domain',$r$Сияющий урон по области, защитные вспышки против атак, временные HP союзникам и поздняя аура света, ослабляющая спасброски врагов.$r$,$r$Домен Света сочетает огонь и сияние с защитой союзников. Он умеет рассеивать Тьму, мешать вражеским атакам и создавать область света, в которой его наступательная магия становится опаснее.$r$,private.cleric_domain_voss('subclass:cleric:light-domain')),
    ('subclass:cleric:nature-domain',$r$Заговор Друида, тяжёлая броня, влияние на зверей и растения, реактивная защита от стихий и стихийный дополнительный урон оружием.$r$,$r$Домен Природы соединяет божественную магию с властью над животными, растениями и стихиями. Он получает часть инструментов Друида, но сохраняет защитный и боевой профиль Жреца.$r$,private.cleric_domain_voss('subclass:cleric:nature-domain')),
    ('subclass:cleric:order-domain',$r$Тяжёлая броня, команды и очарование, немедленные атаки союзников, ускоренное сотворение чар и психический Божественный удар.$r$,$r$Домен Порядка превращает приказы в боевые эффекты. Его заклинания способны немедленно направлять атаки союзников, Божественный канал подчиняет противников, а поздние способности усиливают контроль и совместный урон.$r$,private.cleric_domain_voss('subclass:cleric:order-domain')),
    ('subclass:cleric:peace-domain',$r$Связывает союзников общим бонусом, лечит во время безопасного перемещения, позволяет принимать урон друг за друга и позднее увеличивает дальность и защиту связи.$r$,$r$Домен Мира строится вокруг группы, а не одного персонажа. Связанные союзники помогают друг другу с бросками, могут менять позицию ради защиты товарища и распределяют опасность между собой.$r$,private.cleric_domain_voss('subclass:cleric:peace-domain')),
    ('subclass:cleric:tempest-domain',$r$Тяжёлая броня и воинское оружие, ответный гром или молния, максимизация стихийного урона, отталкивание электричеством и поздний полёт на открытом воздухе.$r$,$r$Домен Бури использует гром и молнию как оружие и контроль пространства. Он выдерживает ближний бой, отвечает атакующим стихией и способен превращать случайный стихийный урон в предельный.$r$,private.cleric_domain_voss('subclass:cleric:tempest-domain')),
    ('subclass:cleric:trickery-domain',$r$Преимущество на Скрытность, управляемый иллюзорный двойник, сотворение заклинаний из позиции копии, перестановка с ней и позднее групповое отвлечение.$r$,$r$Домен Обмана использует скрытность, иллюзии и неверную позицию вместо прямого давления. Его центральный инструмент — двойник, через которого Жрец может отвлекать врагов, перемещаться и направлять магию.$r$,private.cleric_domain_voss('subclass:cleric:trickery-domain')),
    ('subclass:cleric:twilight-domain',$r$Дальнее тёмное зрение, преимущество на инициативу, Сумеречное святилище с временными HP или снятием страха и очарования, полёт в темноте и защитное укрытие ауры.$r$,$r$Домен Сумерек защищает группу на границе света и темноты. Его святилище движется вместе с Жрецом, поддерживает союзников каждый ход и позднее становится полноценным защитным покровом.$r$,private.cleric_domain_voss('subclass:cleric:twilight-domain')),
    ('subclass:cleric:war-domain',$r$Божественная точность через Божественный канал, дополнительные атаки, особое сотворение боевых заклинаний без Концентрации и постоянное сопротивление физическому урону.$r$,$r$Домен Войны предназначен для Жреца, который участвует в передней линии лично. Он усиливает попадания, даёт дополнительные атаки и использует Божественный канал для поддержания ключевых боевых заклинаний.$r$,private.cleric_domain_voss('subclass:cleric:war-domain'))
  ) as v(catalog_key,summary,description,voss)
  where t.campaign_id=p_campaign_id and t.is_active and t.catalog_key=v.catalog_key;

  -- Canonical Voss comments on every feature grant, including nested choices.
  update public.rule_templates t
  set mechanics=private.cleric_voss_mechanics(private.cleric_template_group_voss(t.mechanics)),
      choices=private.cleric_voss_choices(t.choices)
  where t.campaign_id=p_campaign_id and t.is_active
    and (t.id=v_cleric or t.parent_template_id=v_cleric);

  update public.rule_template_levels l
  set mechanics=private.cleric_voss_mechanics(private.cleric_group_voss(l.mechanics,t.catalog_key,l.level)),
      choices=private.cleric_voss_choices(l.choices)
  from public.rule_templates t
  where t.id=l.template_id and t.campaign_id=p_campaign_id and t.is_active
    and (t.id=v_cleric or t.parent_template_id=v_cleric);
end;
$$;

create or replace function private.assert_cleric_text_ready(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cleric uuid;
  v_subclasses integer;
  v_features integer;
  v_bad_feature_text integer;
  v_missing_feature_voss integer;
  v_openable integer;
  v_missing_openable_voss integer;
  v_bad_templates integer;
  v_nested_missing integer;
  v_meta_leaks integer;
begin
  select id into v_cleric from public.rule_templates
  where campaign_id=p_campaign_id and is_active and catalog_key='class:cleric'
  order by version desc limit 1;
  if v_cleric is null then return; end if;

  select count(*) into v_subclasses from public.rule_templates
  where campaign_id=p_campaign_id and is_active and parent_template_id=v_cleric and kind='subclass';
  if v_subclasses<>14 then raise exception 'Cleric TEXT READY requires 14 domains, found %',v_subclasses; end if;

  with templates as (
    select * from public.rule_templates where campaign_id=p_campaign_id and is_active and (id=v_cleric or parent_template_id=v_cleric)
  ), all_mechanics as (
    select t.catalog_key,case when t.kind='subclass' then greatest(1,coalesce(t.unlock_level,1)) else 1 end as level,m
    from templates t cross join lateral jsonb_array_elements(coalesce(t.mechanics,'[]'::jsonb)) m
    union all
    select t.catalog_key,l.level,m from templates t join public.rule_template_levels l on l.template_id=t.id
    cross join lateral jsonb_array_elements(coalesce(l.mechanics,'[]'::jsonb)) m
  )
  select count(*) filter(where m->>'type'='grant' and m->>'target'='feature'),
         count(*) filter(where m->>'type'='grant' and m->>'target'='feature' and (
           coalesce(trim(m->'payload'->>'description'),'')='' or
           lower(coalesce(m->'payload'->>'description','')) ~ '(расширяет возможности|развивает направление|усиливает возможности|получает новые возможности|становится эффективнее|открывает выбор домена|открывает очередную способность)')),
         count(*) filter(where m->>'type'='grant' and m->>'target'='feature' and coalesce(trim(m->'payload'->>'authorComment'),'')='')
    into v_features,v_bad_feature_text,v_missing_feature_voss
  from all_mechanics;
  if v_features<>84 then raise exception 'Cleric TEXT READY requires 84 feature grants including hit die, found %',v_features; end if;
  if v_bad_feature_text<>0 then raise exception 'Cleric has % empty/vague feature descriptions',v_bad_feature_text; end if;
  if v_missing_feature_voss<>0 then raise exception 'Cleric has % feature cards without Voss',v_missing_feature_voss; end if;

  with templates as (
    select * from public.rule_templates where campaign_id=p_campaign_id and is_active and (id=v_cleric or parent_template_id=v_cleric)
  ), rows as (
    select t.catalog_key,case when t.kind='subclass' then greatest(1,coalesce(t.unlock_level,1)) else 1 end as level,coalesce(nullif(trim(m->>'sourceKey'),''),m->>'id') as source_key,m
    from templates t cross join lateral jsonb_array_elements(coalesce(t.mechanics,'[]'::jsonb)) m
    union all
    select t.catalog_key,l.level,coalesce(nullif(trim(m->>'sourceKey'),''),m->>'id'),m
    from templates t join public.rule_template_levels l on l.template_id=t.id cross join lateral jsonb_array_elements(coalesce(l.mechanics,'[]'::jsonb)) m
  ), groups as (
    select catalog_key,level,source_key,
      bool_and(m->>'type'='resource' and m->>'key'~'^spell_slot_[1-9]$') as all_spell_slots,
      max(nullif(trim(case when m->>'type'='grant' and m->>'target'='feature' then m->'payload'->>'authorComment' end),'')) as feature_voss,
      max(nullif(trim(m->'presentation'->>'authorComment'),'')) as presentation_voss
    from rows group by catalog_key,level,source_key
  )
  select count(*) filter(where not all_spell_slots),
         count(*) filter(where not all_spell_slots and coalesce(feature_voss,presentation_voss,'')='')
    into v_openable,v_missing_openable_voss from groups;
  if v_openable<>156 then raise exception 'Cleric reference expected 156 openable groups, found %',v_openable; end if;
  if v_missing_openable_voss<>0 then raise exception 'Cleric has % openable groups without Voss',v_missing_openable_voss; end if;

  select count(*) into v_bad_templates from public.rule_templates
  where campaign_id=p_campaign_id and is_active and (id=v_cleric or parent_template_id=v_cleric)
    and (coalesce(trim(mechanical_summary),'')='' or coalesce(trim(author_description),'')='' or coalesce(trim(author_comment),'')=''
      or lower(coalesce(author_description,'')) like '%сначала разберитесь%');
  if v_bad_templates<>0 then raise exception 'Cleric has % incomplete class/domain overview cards',v_bad_templates; end if;

  -- Nested selectable feature rules must carry the narrator too.
  with choice_roots as (
    select choices from public.rule_templates where id=v_cleric
    union all
    select l.choices from public.rule_template_levels l where l.template_id=v_cleric
  ), choices as (
    select c from choice_roots r cross join lateral jsonb_array_elements(coalesce(r.choices,'[]'::jsonb)) c
  ), nested as (
    select m from choices c cross join lateral jsonb_each(coalesce(c.c->'option_mechanics','{}'::jsonb)) o(k,v)
      cross join lateral jsonb_array_elements(v) m
    union all
    select m from choices c cross join lateral jsonb_each(coalesce(c.c->'option_mechanics_by_level','{}'::jsonb)) o(k,v)
      cross join lateral jsonb_each(v) lv(lk,lval) cross join lateral jsonb_array_elements(lval) m
  )
  select count(*) into v_nested_missing from nested
  where m->>'type'='grant' and m->>'target'='feature' and coalesce(trim(m->'payload'->>'authorComment'),'')='';
  if v_nested_missing<>0 then raise exception 'Cleric has % nested selectable feature rules without Voss',v_nested_missing; end if;

  with templates as (
    select * from public.rule_templates where campaign_id=p_campaign_id and is_active and (id=v_cleric or parent_template_id=v_cleric)
  ), text_parts as (
    select coalesce(mechanical_summary,'')||' '||coalesce(author_description,'')||' '||coalesce(author_comment,'') as txt from templates
    union all
    select coalesce(m->'payload'->>'label','')||' '||coalesce(m->'payload'->>'description','')||' '||coalesce(m->'payload'->>'authorComment','')||' '||coalesce(m->'presentation'->>'authorComment','')
    from templates t cross join lateral jsonb_array_elements(coalesce(t.mechanics,'[]'::jsonb)) m
    union all
    select coalesce(m->'payload'->>'label','')||' '||coalesce(m->'payload'->>'description','')||' '||coalesce(m->'payload'->>'authorComment','')||' '||coalesce(m->'presentation'->>'authorComment','')
    from templates t join public.rule_template_levels l on l.template_id=t.id cross join lateral jsonb_array_elements(coalesce(l.mechanics,'[]'::jsonb)) m
  )
  select count(*) into v_meta_leaks from text_parts where lower(txt) ~ '(character engine|runtime|парсер|миграц|в этой кампании|мы используем|мы изменили|совместимост|редакция правил|2014|2024)';
  if v_meta_leaks<>0 then raise exception 'Cleric player-facing text contains % developer/meta leaks',v_meta_leaks; end if;
end;
$$;

create or replace function private.apply_cleric_text_ready_after_campaign()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.apply_cleric_text_ready(new.id);
  perform private.assert_cleric_text_ready(new.id);
  return new;
end;
$$;

drop trigger if exists zzzzzzzzzzzz_campaigns_cleric_text_ready on public.campaigns;
create trigger zzzzzzzzzzzz_campaigns_cleric_text_ready
after insert on public.campaigns
for each row execute function private.apply_cleric_text_ready_after_campaign();

do $$
declare r record;
begin
  for r in select id from public.campaigns loop
    perform private.apply_cleric_text_ready(r.id);
    perform private.assert_cleric_text_ready(r.id);
  end loop;
end $$;

commit;
